34:  function attachEvent(selector, event, fn) {
35:    const matches = typeof selector === 'string' ? document.querySelectorAll(selector) : selector;
36:    if (matches && matches.length) {
37:      matches.forEach((elem) => {
38:        elem.addEventListener(event, (e) => fn(e, elem), false);
39:      });
