41:  }
42:
43:  const onLoad = function () {
44:    let lastKnownScrollPosition = window.scrollY;
45:    let ticking = true;
46:
47:    attachEvent('#header nav', 'click', function () {
48:      document.querySelector('[data-aw-toggle-menu]')?.classList.remove('expanded');
