68:      if (defaultTheme.endsWith(':only')) {
69:        return;
70:      }
71:
72:      Observer.removeAnimationDelay();
73:
74:      document.documentElement.classList.toggle('dark');
75:      localStorage.theme = document.documentElement.classList.contains('dark') ? 'dark' : 'light';
76:    });
77:
78:    attachEvent('[data-aw-social-share]', 'click', function (_, elem) {
79:      const network = elem.getAttribute('data-aw-social-share');
80:      const url = encodeURIComponent(elem.getAttribute('data-aw-url'));
81:      const text = encodeURIComponent(elem.getAttribute('data-aw-text'));
82:
83:      let href;
84:      switch (network) {
85:        case 'facebook':
86:          href = `https://www.facebook.com/sharer.php?u=${url}`;
87:          break;
88:        case 'twitter':
89:          href = `https://twitter.com/intent/tweet?url=${url}&text=${text}`;
90:          break;
91:        case 'linkedin':
92:          href = `https://www.linkedin.com/shareArticle?mini=true&url=${url}&title=${text}`;
93:          break;
94:        case 'whatsapp':
95:          href = `https://wa.me/?text=${text}%20${url}`;
96:          break;
97:        case 'mail':
98:          href = `mailto:?subject=%22${text}%22&body=${text}%20${url}`;
99:          break;
100:
101:        default:
102:          return;
103:      }
104:
105:      const newlink = document.createElement('a');
106:      newlink.target = '_blank';
107:      newlink.href = href;
108:      newlink.click();
109:    });
